				nodes.Literal = removeInvalidNodeErrorsInLiteral;
				nodes.TemplateElement = skipTemplates
					? removeInvalidNodeErrorsInTemplateLiteral
					: noop;
				nodes.JSXText = skipJSXText
					? removeInvalidNodeErrorsInJSXText
					: noop;
