			const [
				{
					allow,
					allowAfterSuper,
					allowAfterThis,
					allowAfterThisConstructor,
					allowFunctionParams,
					allowInArrayDestructuring,
					allowInObjectDestructuring,
					enforceInClassFields,
					enforceInMethodNames,
				},
			] = context.options;
			const sourceCode = context.sourceCode;

